alter table alive_private.story_endings add column opening text, add column closing text;
update alive_private.story_endings e set opening=v.opening, skill_clues=v.passages, closing=v.closing from (values
('MEDIEVAL_PLAGUE_QUEEN','Каждую осень Янтарный Король зовёт вас на пир. На этот раз музыканты успели сыграть всего три ноты. В витраж ударилась болотная ворона, и за окном белые яблони почернели до самых корней. Облако Чумной Королевы доберётся до замка через три рассвета.

Король отодвинул кубок. «У старой часовни висит колокол. Пока цела цепь, что связывает его с Королевой, туча будет идти за звоном. До часовни два дня пути. Воды берите по четыре литра на спутника. Мест в моей повозке — {места}. Остальных я прошу помочь вывести людей из замка».

Он раскрыл последнее донесение и прочёл вслух:',array['«У часовни остался раненый гонец. Дорогу назад знает он один. Возьмите того, кому вы доверили бы перевязать друга в темноте и довезти его живым».','«На цепи уже сломали два топора. Старый литейщик говорил, что у всякого звена есть слабая сторона. Будь с вами кто-нибудь, кто и сам работал с железом, хватило бы одного удара».','«К колоколу ведёт дверь шириной в один щит. Пока у цепи будут заняты руки, кому-то придётся удержать порог. Тот, кто когда-нибудь прикрывал спину товарищу, поймёт, где встать».','«На гати из бурдюков выбивает пробки. Дальше возчики видели только чёрную жижу да камыш. Кто умеет находить под болотной водой чистый ключ, тот доведёт отряд до часовни».','«Дорога на королевской карте кончается посреди трясины. А ведь когда-то по ней возили муку. Человек, умеющий читать старые межи и следы настила, ещё найдёт переправу».','«На колоколе проступают письмена. Чем сильнее тянут за цепь, тем громче он звонит. Среди вас есть кто-нибудь, кому доводилось распутывать старые чары? Пусть взглянет на знаки прежде, чем остальные возьмутся за железо».'],'Король сложил письмо. Во дворе уже запрягали мула. Осталось решить, кому сесть в повозку.'),
('SC01','После ядерной зимы поверхность на долгие годы стала непригодной для жизни. Вы нашли убежище с реактором и воздухоочисткой. У железных переборок почти невозможно прожить без защиты тому, кто тяжело переносит контакт с металлом.

На обороте сменного журнала дежурный оставил записи для тех, кто придёт следом.',array['Бумажная лента у решётки больше не шевелится. Тот, кто отличит забитый воздуховод от остановленного вентилятора, вернёт воздух в спальни.','Внизу стоят пустые грядки и лампы. До следующего урожая хватит крупы, если среди вас найдётся человек, который уже выращивал еду без солнца.','У входа лежат два одинаково чистых с виду плаща. Один помечен мелом. Кто сумеет проверить вещи с поверхности, прежде чем их внесут в жилой отсек?','При запуске насоса в спальнях гаснут лампы. Здесь особенно пригодится человек, умеющий распределить нагрузку так, чтобы воздух продолжал идти.','Снаружи мешки с зерном сухие, но от дальней стены погреба тянет сладковатым запахом. Опытный кладовщик успел бы отделить испорченное.','Чистой воды остаётся всё меньше, а отстойник полон. В старых трубах разберётся тот, кто уже возвращал воду в оборот.'],'На последней странице оставлено место для подписи новой смены.'),
('SC02','Океан поглотил равнину. Несколько крыш ещё выступают из воды, но к утру исчезнут и они. Вы поднимаетесь на плавучий модуль. Внутри есть опреснитель, сети и карта последних известных возвышенностей.

Перед отплытием вы обходите палубу.',array['Вода из крана отдаёт солью. В море очень пригодится человек, который знает, почему исправный с виду опреснитель пропускает рассол.','При каждом крене один из швов темнеет. Если кто-нибудь умеет слушать, как работает обшивка под нагрузкой, у вас ещё есть время укрепить её.','Последнюю вышку уже не видно. Вахтенному, умеющему держать курс по звёздам и течению, скоро придётся вести остальных.','В сетях трепещет серебристая рыба. Человек, знающий здешний улов и умеющий беречь его в тепле, сможет накормить весь модуль.','По тенту стекает первый ливень, и вся вода уходит за борт. Кто умеет собирать и хранить её чистой, тому стоит остаться на палубе.','Перед закатом ветер вдруг стих, а вдалеке побелела вода. Опытный наблюдатель ещё успеет предугадать удар шторма.'],'Швартов уже натянут. Пора решить, кто останется на борту.'),
('SC03','После псионического шторма в городе остались целые дома и совсем мало людей, способных узнать свой подъезд. Вы нашли убежище с защищёнными комнатами и автономным питанием.

На стене кто-то записал последние часы дежурства.',array['Перед приступом соседи начинают произносить одну и ту же мысль. Внутри пригодится человек, умеющий помочь другому удержаться в собственном сознании.','За минуту до удара на ленте приборов всякий раз появляется короткая черта. Кто сумеет прочесть её вовремя, даст остальным минуту на укрытие.','В дальней комнате стулья остаются на месте даже во время шторма. Похоже, кто-то понимал, как поддерживать её защитное поле.','Двое видели у двери одного и того же посетителя, но описали разные лица. Здесь будут особенно ценить человека, умеющего спокойно перепроверять увиденное вместе с другими.','Прямой путь к складу проходит мимо вокзала, где всё ещё слышна толпа. Старожил, знающий обход пустыми дворами, может вернуть разведчиков домой.','После каждой тревоги кто-нибудь забывает собственное имя. Нужен спутник, который уже помогал людям приходить в себя после потрясения.'],'Под записью дрожащей рукой приписано: «Решите, кому вы доверите следующую смену».'),
('SC04','На поверхности −60 °C. От прежней станции осталась лестница под снегом, но за нижней дверью ещё тепло. Геотермальный контур работает, утеплённые жилые отсеки уцелели.

При осмотре вы замечаете первые следы долгой зимовки.',array['У скважины труба горячая, а у спален едва тёплая. Человек, понимающий ход теплоносителя, может вернуть тепло людям.','На одном из внутренних швов вырос гребень инея. На вес золота будет тот, кто сумеет найти и закрыть утечку тепла.','Стрелка давления понемногу опускается, хотя двери закрыты. Найдётся ли среди вас кто-то, кто умеет искать едва заметную утечку воздуха?','Льда вокруг сколько угодно, питья хватит ненадолго. Тот, кто уже добывал воду на зимовке, сумеет сберечь драгоценное топливо.','Возле тёплой трубы из рассыпанного зерна взошли два ростка. Для опытного огородника здесь найдётся крошечная полоска земли.','Соседний купол иногда мигает в ясную погоду. Переход стоит доверить тому, кто умеет читать лёд и вовремя повернуть назад.'],'За дверью уже смеркается. Сегодня уйти дальше не получится.'),
('SC05','Шторм унёс лайнер. Вы остались в спасательной лодке. Воды примерно на три дня, до острова при удачном курсе — сутки. Ночью вас уже отнесло от места крушения.

На рассвете становится виднее, с чем вы вышли в море.',array['Под скамьёй собирается тонкая струйка. Тот, кто уже латал лодки на воде, успеет удержать повреждённый стык.','На горизонте показался дым и почти сразу исчез. Кто знает, как подать заметный сигнал, получит ещё один шанс к вечеру.','Остров за ночь сместился далеко вправо от носа. Без человека, умеющего учитывать снос течением, можно весь день грести мимо.','За бортом кружит незнакомая рыба. Будет легче, если кто-нибудь узнает здешний улов и сумеет приготовить его.','Солёная вода уже попала в один кувшин. Тент цел, и тот, кто собирал дождь в море, ещё сможет пополнить запас.','У двоих промокла одежда, один так и не разогнул ушибленную руку. Кто умеет ухаживать за пострадавшими в пути, даст им шанс дождаться берега.'],'Лодку опять развернуло боком. Пора распределить места.'),
('SC06','К ночи заражённые стягиваются на шум. Вы заперлись в укрытии с баррикадами и работающей фильтрацией. За стеной давно смолкли городские сети.

У входа осталась записка предыдущей смены.',array['Из смотровой тянет воздухом прямо в спальню. Человек, понимающий вентиляцию, сумеет изолировать отсек.','За ночь засов дважды вышел из пазов. У входа нужен тот, кто сумеет укрепить дверь и оставить людям путь из здания.','Генератор слышен даже со двора. Тот, кто разбирается в тихом резервном питании, поможет пережить следующую ночь.','После последнего выхода никто не помнит, кто с кем дежурил. Пригодится человек, способный восстановить контакты и организовать наблюдение.','Магазин за путепроводом ещё цел, но после заката пройти обратно невозможно. Выручит тот, кто умеет планировать короткие дневные выходы.','Вчера после ливня затопило двор у питьевой цистерны. Спасти запас сможет человек, понимающий, как отсечь грязный сток.'],'На листке нет подписи. Снаружи уже слышатся шаги.'),
('SC07','Туман поглотил почти весь дневной свет. Существа снаружи охотятся на звук, а вернувшиеся порой забывают, какой дорогой шли. У входа кто-то так и застыл, потеряв из виду стены. В здешней темноте поддержка человека или знакомый набор самопомощи могут решить его судьбу.

Вы проходите вдоль стены последнего убежища.',array['На обратном пути даже вход исчезает в двух шагах. Проводник, умеющий оставлять осязаемый путь домой, сможет вывести людей вслепую.','У пола тянется полоска тумана. Кто умеет держать воздух в убежище чистым, заметит, откуда он пробирается.','Щебень под воротами громче шагов. Для разведки понадобится спутник, который проведёт остальных так, что снаружи никто не обернётся.','Дежурный видел тень за воротами, но побоялся окликнуть смену. Тот, кто сумеет наладить беззвучное предупреждение, даст людям время.','В короткий светлый час в оранжерее раскрываются листья. Кто работал с культурами при слабом свете, ещё сумеет получить урожай.','На одном указателе все прочли разные названия. Человек, умеющий перепроверять ориентиры и воспоминания вместе с товарищем, поможет группе не потеряться.'],'До следующего короткого просвета придётся оставаться внутри.'),
('water_world','После затопления вы живёте на плавучей платформе. Воду собирают с крыши, под палубой стоит резервный дизель, а в радиорубке до сих пор отмечают слухи о суше.

Утром дежурный передаёт вахту.',array['Цистерна уже наполовину пуста, а небо чистое. Пригодился бы человек, умеющий получать пресную воду из забортной.','При встречной волне одна секция корпуса ходит отдельно от остальных. Кто понимает, как связаны её рёбра, сможет удержать платформу.','После общей вахты у двоих начался жар. Среди вас особенно нужен тот, кто заметит новые случаи и восстановит круг контактов.','За кормой идёт косяк, но наживку срывают с пустых крючков. Опытный рыбак сумеет и накормить людей, и отложить часть улова.','Даже внутри шкафа под крышкой проступают капли. Тот, кто умеет сохранять сухими припасы и приборы, может спасти оба запаса.','Два сообщения о береговых огнях указывают в разные стороны. Кто умеет сверять морские наблюдения и курс, отделит землю от слухов.'],'На палубе ждут вашего решения о составе следующей смены.')
) v(id,opening,passages,closing) where e.scenario_id=v.id;

create or replace function alive_private.room_story(p_code text) returns text
language sql stable security definer set search_path='' as $$
 select replace(e.opening,'{места}',coalesce(nullif(r.settings->>'target_survivors',''),'1'))
 ||E'\n\n'||string_agg(e.skill_clues[z.idx],E'\n\n' order by z.idx)||E'\n\n'||e.closing
 ||case when r.current_phase='finished' then E'\n\n'||case when r.verdict='victory' then e.victory else e.defeat end else '' end
 from public.rooms r join alive_private.story_endings e on e.scenario_id=r.scenario_id
 cross join lateral (select distinct i idx from generate_series(1,6) i
 join alive_private.room_combos c on c.route=r.scenario_id||'_route_'||i and c.room_code=r.code) z
 where r.code=p_code and alive_private.member(r.code) and (r.scenario_visible or alive_private.host(r.code))
 and r.card_mode<>'preset' and alive_private.scenario_combos_enabled(r.scenario_id)
 group by r.code,r.current_phase,r.verdict,e.opening,e.closing,e.victory,e.defeat having count(*)=2
$$;
